selector_to_html = {"a[href=\"#inference-evaluation-setup\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Inference Evaluation Setup<a class=\"headerlink\" href=\"#inference-evaluation-setup\" title=\"Link to this heading\">#</a></h3><p>Example host configuration:</p>", "a[href=\"#overview\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Overview<a class=\"headerlink\" href=\"#overview\" title=\"Link to this heading\">#</a></h2><p><strong>FlagPerf</strong> is an integrated AI hardware benchmarking engine co-built by BAAI (Beijing Academy of Artificial Intelligence) and AI hardware vendors. It aims to establish an industry practice-oriented metric system for evaluating AI hardware capabilities under software stack combinations (model + framework + compiler).</p><p>FlagPerf provides a comprehensive evaluation framework that covers multiple dimensions of AI hardware performance, including computing power, memory bandwidth, interconnect capabilities, and energy consumption.</p>", "a[href=\"#contact\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Contact<a class=\"headerlink\" href=\"#contact\" title=\"Link to this heading\">#</a></h2><p>For questions and support:</p>", "a[href=\"#supported-evaluation-modules\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Supported Evaluation Modules<a class=\"headerlink\" href=\"#supported-evaluation-modules\" title=\"Link to this heading\">#</a></h2><h3>Base Specifications List<a class=\"headerlink\" href=\"#base-specifications-list\" title=\"Link to this heading\">#</a></h3><p>The base specifications evaluation covers 13 items across 4 categories:</p>", "a[href=\"#hardware-environment\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Hardware Environment<a class=\"headerlink\" href=\"#hardware-environment\" title=\"Link to this heading\">#</a></h3><p>For physical machine deployment (default):</p>", "a[href=\"#training-module\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Training Module<a class=\"headerlink\" href=\"#training-module\" title=\"Link to this heading\">#</a></h3><p>Supports 44+ models including:</p>", "a[href=\"#configuration-reference\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Configuration Reference<a class=\"headerlink\" href=\"#configuration-reference\" title=\"Link to this heading\">#</a></h2><h3>Test Configuration Format<a class=\"headerlink\" href=\"#test-configuration-format\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#vendor-adaptation\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Vendor Adaptation<a class=\"headerlink\" href=\"#vendor-adaptation\" title=\"Link to this heading\">#</a></h3><p>Vendors can adapt FlagPerf for their hardware by:</p>", "a[href=\"#partners\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Partners<a class=\"headerlink\" href=\"#partners\" title=\"Link to this heading\">#</a></h2><p>FlagPerf is co-built with AI hardware vendors including:</p>", "a[href=\"#system-requirements\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">System Requirements<a class=\"headerlink\" href=\"#system-requirements\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#key-features\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Key Features<a class=\"headerlink\" href=\"#key-features\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#flagperf-user-guide\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">FlagPerf User Guide<a class=\"headerlink\" href=\"#flagperf-user-guide\" title=\"Link to this heading\">#</a></h1><h2>Overview<a class=\"headerlink\" href=\"#overview\" title=\"Link to this heading\">#</a></h2><p><strong>FlagPerf</strong> is an integrated AI hardware benchmarking engine co-built by BAAI (Beijing Academy of Artificial Intelligence) and AI hardware vendors. It aims to establish an industry practice-oriented metric system for evaluating AI hardware capabilities under software stack combinations (model + framework + compiler).</p><p>FlagPerf provides a comprehensive evaluation framework that covers multiple dimensions of AI hardware performance, including computing power, memory bandwidth, interconnect capabilities, and energy consumption.</p>", "a[href=\"#training-evaluation-setup\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Training Evaluation Setup<a class=\"headerlink\" href=\"#training-evaluation-setup\" title=\"Link to this heading\">#</a></h3><p>Example cluster configuration:</p>", "a[href=\"#contributing\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Contributing<a class=\"headerlink\" href=\"#contributing\" title=\"Link to this heading\">#</a></h2><p>FlagPerf adopts an open-source collaborative approach:</p>", "a[href=\"#standard-case-development\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Standard Case Development<a class=\"headerlink\" href=\"#standard-case-development\" title=\"Link to this heading\">#</a></h3><p>Standard cases are model-framework combinations that serve as reference implementations. They:</p>", "a[href=\"#license\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">License<a class=\"headerlink\" href=\"#license\" title=\"Link to this heading\">#</a></h2><p>FlagPerf is released under the Apache 2.0 license.</p>", "a[href=\"#test-configuration-format\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Test Configuration Format<a class=\"headerlink\" href=\"#test-configuration-format\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#getting-started\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Getting Started<a class=\"headerlink\" href=\"#getting-started\" title=\"Link to this heading\">#</a></h2><h3>Quick Start (Training Example)<a class=\"headerlink\" href=\"#quick-start-training-example\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#installation\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Installation<a class=\"headerlink\" href=\"#installation\" title=\"Link to this heading\">#</a></h2><h3>System Requirements<a class=\"headerlink\" href=\"#system-requirements\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#inference-module\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Inference Module<a class=\"headerlink\" href=\"#inference-module\" title=\"Link to this heading\">#</a></h3><p>Supports 11 models:</p>", "a[href=\"#base-specifications\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Base Specifications<a class=\"headerlink\" href=\"#base-specifications\" title=\"Link to this heading\">#</a></h3><p>The base specifications evaluation module provides comprehensive testing of AI hardware capabilities:</p><p><strong>Computing Power</strong>: FP64, FP32, TF32, FP16, BF16, INT8\n<strong>Memory</strong>: Main memory bandwidth and capacity\n<strong>Interconnect</strong>: CPU-chip, intra-server P2P/MPI, inter-server P2P/MPI\n<strong>Energy</strong>: Power consumption monitoring</p>", "a[href=\"#quick-start-training-example\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Quick Start (Training Example)<a class=\"headerlink\" href=\"#quick-start-training-example\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#module-details\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Module Details<a class=\"headerlink\" href=\"#module-details\" title=\"Link to this heading\">#</a></h2><h3>Base Specifications<a class=\"headerlink\" href=\"#base-specifications\" title=\"Link to this heading\">#</a></h3><p>The base specifications evaluation module provides comprehensive testing of AI hardware capabilities:</p><p><strong>Computing Power</strong>: FP64, FP32, TF32, FP16, BF16, INT8\n<strong>Memory</strong>: Main memory bandwidth and capacity\n<strong>Interconnect</strong>: CPU-chip, intra-server P2P/MPI, inter-server P2P/MPI\n<strong>Energy</strong>: Power consumption monitoring</p>", "a[href=\"#base-specifications-list\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Base Specifications List<a class=\"headerlink\" href=\"#base-specifications-list\" title=\"Link to this heading\">#</a></h3><p>The base specifications evaluation covers 13 items across 4 categories:</p>", "a[href=\"#base-specifications-evaluation-setup\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Base Specifications Evaluation Setup<a class=\"headerlink\" href=\"#base-specifications-evaluation-setup\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#generate-module\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Generate Module<a class=\"headerlink\" href=\"#generate-module\" title=\"Link to this heading\">#</a></h3><p>For large language model generative inference evaluation:</p>", "a[href=\"#viewing-results\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Viewing Results<a class=\"headerlink\" href=\"#viewing-results\" title=\"Link to this heading\">#</a></h2><p>Training logs are located in:</p>", "a[href=\"#environment-variables\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Environment Variables<a class=\"headerlink\" href=\"#environment-variables\" title=\"Link to this heading\">#</a></h3>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
